$db->exec("CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE,name TEXT,password TEXT,role TEXT,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,name TEXT,sku TEXT UNIQUE,price REAL,stock INTEGER DEFAULT 0,min_stock INTEGER DEFAULT 3,active INTEGER DEFAULT 1);
