CREATE TABLE IF NOT EXISTS cash_sessions(id INTEGER PRIMARY KEY,opened_at TEXT DEFAULT CURRENT_TIMESTAMP,closed_at TEXT,opening REAL,closing REAL,user_id INTEGER,status TEXT DEFAULT 'abierta');");
foreach(['ALTER TABLE products ADD COLUMN category TEXT DEFAULT \'General\'','ALTER TABLE products ADD COLUMN variant TEXT DEFAULT \'\'','ALTER TABLE orders ADD COLUMN reserved_until TEXT'] as $migration){try{$db->exec($migration);}catch(Throwable $ignore){}}
$db->exec("CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT); CREATE TABLE IF NOT EXISTS payment_proofs(id INTEGER PRIMARY KEY,order_id INTEGER,storage_key TEXT,original_name TEXT,mime TEXT,bytes INTEGER,sha256 TEXT,uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP,status TEXT DEFAULT 'informado',reviewer_id INTEGER,reviewed_at TEXT,observation TEXT); CREATE TABLE IF NOT EXISTS order_events(id INTEGER PRIMARY KEY,order_id INTEGER,actor_id INTEGER,event TEXT,from_status TEXT,to_status TEXT,note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);");
foreach(['ALTER TABLE orders ADD COLUMN payment_deadline TEXT','ALTER TABLE orders ADD COLUMN upload_token TEXT'] as $migration){try{$db->exec($migration);}catch(Throwable $ignore){}}
foreach(['bank_holder'=>'Laboratorio Digital','bank_alias'=>'laboratorio.digital','bank_cbu'=>'0000003100000000000000','payment_hours'=>'2'] as $k=>$v){$s=$db->prepare('INSERT OR IGNORE INTO settings(key,value) VALUES(?,?)');$s->execute([$k,$v]);}
if(!(int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn()) { $db->prepare('INSERT INTO users(email,name,password,role) VALUES(?,?,?,?)')->execute(['admin@local','Administración',password_hash('admin123',PASSWORD_DEFAULT),'admin']); $products=[['Remera básica','REM-001',12990,18,4],['Jean recto','JEA-002',28990,9,3],['Zapatilla urbana','ZAP-003',45990,6,2],['Mochila clásica','MOC-004',24990,12,3],['Gorra lisa','GOR-005',8990,22,5]]; $q=$db->prepare('INSERT INTO products(name,sku,price,stock,min_stock) VALUES(?,?,?,?,?)'); foreach($products as $p)$q->execute($p); }
function user(){return $_SESSION['user']??null;} function out($x){echo htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');} function json($x){header('Content-Type: application/json');echo json_encode($x);exit;} function requireLogin(){if(!user())json(['error'=>'No autorizado']);}
if($_SERVER['REQUEST_METHOD']==='POST') { $in=json_decode(file_get_contents('php://input'),true)??$_POST; $action=$in['action']??'';
 try {
 if($action==='upload_proof'){ $id=(int)($in['order_id']??0);$token=$in['token']??'';$q=$db->prepare('SELECT * FROM orders WHERE id=? AND upload_token=?');$q->execute([$id,$token]);$o=$q->fetch(PDO::FETCH_ASSOC);if(!$o||!in_array($o['status'],['pendiente_pago','rechazado'],true))throw new Exception('Este enlace ya no admite comprobantes');if(strtotime($o['payment_deadline'])<time())throw new Exception('La reserva venció');if(empty($_FILES['proof'])||$_FILES['proof']['error']!==UPLOAD_ERR_OK)throw new Exception('No se pudo recibir el archivo');if($_FILES['proof']['size']>8*1024*1024)throw new Exception('El archivo supera 8 MB');$fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($_FILES['proof']['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf'];if(!isset($allowed[$mime]))throw new Exception('Solo se aceptan JPG, PNG o PDF');$dir=$dbDir.'/proofs';if(!is_dir($dir))mkdir($dir,0775,true);$key=bin2hex(random_bytes(18)).'.'.$allowed[$mime];if(!move_uploaded_file($_FILES['proof']['tmp_name'],$dir.'/'.$key))throw new Exception('No se pudo guardar el archivo');$db->prepare('INSERT INTO payment_proofs(order_id,storage_key,original_name,mime,bytes,sha256) VALUES(?,?,?,?,?,?)')->execute([$id,$key,basename($_FILES['proof']['name']),$mime,$_FILES['proof']['size'],hash_file('sha256',$dir.'/'.$key)]);$db->prepare("UPDATE orders SET status='pago_informado' WHERE id=?")->execute([$id]);$db->prepare('INSERT INTO order_events(order_id,event,from_status,to_status,note) VALUES(?,?,?,?,?)')->execute([$id,'comprobante cargado',$o['status'],'pago_informado','Pendiente de verificación']);json(['ok'=>true]); }
 if($action==='login'){ $s=$db->prepare('SELECT * FROM users WHERE email=? AND active=1');$s->execute([$in['email']??'']);$u=$s->fetch(PDO::FETCH_ASSOC); if(!$u||!password_verify($in['password']??'',$u['password']))json(['error'=>'Credenciales inválidas']); unset($u['password']);$_SESSION['user']=$u;json(['ok'=>true,'user'=>$u]); }
 if($action==='logout'){session_destroy();json(['ok'=>true]);}
 if($action==='order'){ $items=$in['items']??[];if(!$items)throw new Exception('El pedido está vacío');$channel=$in['channel']??'online';$reserved=in_array($channel,['online','whatsapp'],true);$hours=(int)$db->query("SELECT value FROM settings WHERE key='payment_hours'")->fetchColumn();$deadline=date('Y-m-d H:i:s',time()+max(1,$hours)*3600);$token=bin2hex(random_bytes(20));$db->beginTransaction();$total=0;$resolved=[];$p=$db->prepare('SELECT * FROM products WHERE id=? AND active=1');foreach($items as $i){$p->execute([(int)$i['id']]);$x=$p->fetch(PDO::FETCH_ASSOC);if(!$x||$x['stock']<(int)$i['qty'])throw new Exception('Stock insuficiente');$resolved[]=[$x,(int)$i['qty']];$total+=$x['price']*(int)$i['qty'];}$status=$reserved?'pendiente_pago':'confirmado';$q=$db->prepare('INSERT INTO orders(channel,customer,total,payment,status,reserved_until,payment_deadline,upload_token,user_id) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$channel,trim($in['customer']??'Consumidor final'),$total,$in['payment']??'pendiente',$status,$reserved?$deadline:null,$reserved?$deadline:null,$reserved?$token:null,user()['id']??null]);$oid=$db->lastInsertId();foreach($resolved as [$x,$qty]){$db->prepare('INSERT INTO order_items(order_id,product_id,qty,price) VALUES(?,?,?,?)')->execute([$oid,$x['id'],$qty,$x['price']]);$db->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$qty,$x['id']]);$db->prepare('INSERT INTO stock_moves(product_id,qty,reason,reference,user_id) VALUES(?,?,?,?,?)')->execute([$x['id'],-$qty,$reserved?'Reserva':'Venta','#'.$oid,user()['id']??null]);}$db->prepare('INSERT INTO order_events(order_id,event,to_status,note) VALUES(?,?,?,?)')->execute([$oid,'pedido creado',$status,'Reserva temporal']);$db->commit();$bank=$db->query("SELECT key,value FROM settings WHERE key IN ('bank_holder','bank_alias','bank_cbu')")->fetchAll(PDO::FETCH_KEY_PAIR);json(['ok'=>true,'order'=>$oid,'total'=>$total,'reserved'=>$reserved,'deadline'=>$deadline,'token'=>$token,'bank'=>$bank]); }
 requireLogin();
 if($action==='review_payment'){if(user()['role']!=='admin')throw new Exception('Solo administración puede verificar pagos');$id=(int)$in['order_id'];$decision=$in['decision']==='aprobar'?'pagado_preparar':'rechazado';$note=trim($in['observation']??'');$o=$db->prepare('SELECT status FROM orders WHERE id=?');$o->execute([$id]);$old=$o->fetchColumn();if($old!=='pago_informado')throw new Exception('El pedido no tiene un pago informado para revisar');$db->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$decision,$id]);$db->prepare('UPDATE payment_proofs SET status=?,reviewer_id=?,reviewed_at=CURRENT_TIMESTAMP,observation=? WHERE order_id=? AND status=?')->execute([$decision,user()['id'],$note,$id,'informado']);$db->prepare('INSERT INTO order_events(order_id,actor_id,event,from_status,to_status,note) VALUES(?,?,?,?,?,?)')->execute([$id,user()['id'],$decision==='pagado_preparar'?'pago aprobado':'pago rechazado',$old,$decision,$note]);json(['ok'=>true]);}
 if($action==='product'){ $db->prepare('INSERT INTO products(name,sku,price,stock,min_stock,category,variant) VALUES(?,?,?,?,?,?,?)')->execute([trim($in['name']),trim($in['sku']),floatval($in['price']),intval($in['stock']),intval($in['min_stock']??3),trim($in['category']??'General'),trim($in['variant']??'')]);json(['ok'=>true]);}
 if($action==='user'){if(user()['role']!=='admin')throw new Exception('Solo administración puede crear usuarios');$db->prepare('INSERT INTO users(email,name,password,role) VALUES(?,?,?,?)')->execute([trim($in['email']),trim($in['name']),password_hash($in['password'],PASSWORD_DEFAULT),$in['role']==='vendedor'?'vendedor':'admin']);json(['ok'=>true]);}
 if($action==='stock'){ $id=intval($in['product_id']);$qty=intval($in['qty']);if(!$qty)throw new Exception('Ingrese una cantidad');$db->beginTransaction();$db->prepare('UPDATE products SET stock=stock+? WHERE id=?')->execute([$qty,$id]);$db->prepare('INSERT INTO stock_moves(product_id,qty,reason,reference,user_id) VALUES(?,?,?,?,?)')->execute([$id,$qty,trim($in['reason']??'Ajuste'),'Manual',user()['id']]);$db->commit();json(['ok'=>true]);}
 if($action==='order_status'){if(user()['role']!=='admin')throw new Exception('Solo administración puede modificar pedidos');$id=intval($in['id']);$status=$in['status'];$o=$db->prepare('SELECT * FROM orders WHERE id=?');$o->execute([$id]);$order=$o->fetch(PDO::FETCH_ASSOC);if(!$order)throw new Exception('Pedido inexistente');if($status==='cancelado'&&$order['status']!=='cancelado'){$items=$db->prepare('SELECT product_id,qty FROM order_items WHERE order_id=?');$items->execute([$id]);foreach($items as $item){$db->prepare('UPDATE products SET stock=stock+? WHERE id=?')->execute([$item['qty'],$item['product_id']]);$db->prepare('INSERT INTO stock_moves(product_id,qty,reason,reference,user_id) VALUES(?,?,?,?,?)')->execute([$item['product_id'],$item['qty'],'Cancelación','#'.$id,user()['id']]);}}$db->prepare('UPDATE orders SET status=?,reserved_until=NULL WHERE id=?')->execute([$status,$id]);json(['ok'=>true]);}
 if($action==='cash'){ $open=$db->query("SELECT * FROM cash_sessions WHERE status='abierta' ORDER BY id DESC LIMIT 1")->fetch();if($open){$db->prepare("UPDATE cash_sessions SET closed_at=CURRENT_TIMESTAMP,closing=?,status='cerrada' WHERE id=?")->execute([floatval($in['amount']),$open['id']]);}else{$db->prepare('INSERT INTO cash_sessions(opening,user_id) VALUES(?,?)')->execute([floatval($in['amount']),user()['id']]);}json(['ok'=>true]);}
 if($action==='backup'){header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="pedidos-pos-'.date('Ymd-His').'.sqlite"');readfile($dbDir.'/pos.sqlite');exit;}
 } catch(Throwable $e){if($db->inTransaction())$db->rollBack();json(['error'=>$e->getMessage()]);}
}
$products=$db->query('SELECT * FROM products WHERE active=1 ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);$categories=$db->query("SELECT DISTINCT category FROM products WHERE active=1 ORDER BY category")->fetchAll(PDO::FETCH_COLUMN);$orders=$db->query('SELECT * FROM orders ORDER BY id DESC LIMIT 8')->fetchAll(PDO::FETCH_ASSOC);$low=$db->query('SELECT * FROM products WHERE stock<=min_stock ORDER BY stock')->fetchAll(PDO::FETCH_ASSOC);$users=user()?$db->query('SELECT name,email,role FROM users WHERE active=1 ORDER BY name')->fetchAll(PDO::FETCH_ASSOC):[];$today=floatval($db->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE date(created_at)=date('now','localtime')")->fetchColumn());$cash=$db->query("SELECT * FROM cash_sessions WHERE status='abierta' ORDER BY id DESC LIMIT 1")->fetch(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VendeSimple · Pedidos y POS</title><style>
:root{--ink:#14213d;--blue:#176bdb;--mint:#eaf7f0;--line:#dde3ee;--danger:#c93636}*{box-sizing:border-box}body{margin:0;font:15px system-ui,sans-serif;color:var(--ink);background:#f6f8fc}header{background:var(--ink);color:white;padding:18px max(5vw,24px);display:flex;justify-content:space-between;align-items:center}h1{font-size:20px;margin:0}button{border:0;border-radius:8px;padding:10px 14px;background:var(--blue);color:white;font-weight:650;cursor:pointer}button.alt{background:white;color:var(--ink)}main{max-width:1180px;margin:auto;padding:26px 5vw}.tabs{display:flex;gap:8px;overflow:auto;margin-bottom:22px}.tabs button{white-space:nowrap;background:#e7edf8;color:var(--ink)}.tabs button.active{background:var(--ink);color:#fff}.page{display:none}.page.active{display:block}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#fff;padding:18px;border:1px solid var(--line);border-radius:12px}.metric{font-size:26px;font-weight:750;margin-top:8px}.products{display:grid;grid-template-columns:repeat(auto-fill,minmax(205px,1fr));gap:14px}.product h3{margin:0 0 6px}.price{font-size:20px;font-weight:700}.stock{color:#557; margin:8px 0}table{width:100%;border-collapse:collapse;background:white;border-radius:12px;overflow:hidden}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line)}th{font-size:12px;color:#64708a}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.cart{position:sticky;bottom:12px;margin-top:20px;background:var(--ink);color:white;padding:16px;border-radius:12px;display:flex;justify-content:space-between;align-items:center}.notice{background:#fff4e4;border:1px solid #f5d49a;padding:14px;border-radius:10px;margin-bottom:14px}.modal{display:none;position:fixed;inset:0;background:#0007;place-items:center;padding:20px}.modal.show{display:grid}.dialog{background:white;padding:24px;border-radius:14px;width:min(450px,100%)}input,select{width:100%;padding:10px;border:1px solid var(--line);border-radius:8px;margin:5px 0 12px;font:inherit}.muted{color:#667085}.pill{padding:3px 8px;border-radius:20px;background:var(--mint);color:#14734c;font-size:12px}@media(max-width:700px){.grid{grid-template-columns:repeat(2,1fr)}table{font-size:13px}th:nth-child(3),td:nth-child(3){display:none}main{padding:18px}.cart{flex-direction:column;align-items:stretch;gap:10px}}
</style></head><body><header><h1>VendeSimple <small class="muted">Pedidos + POS</small></h1><div id="identity"><?php if(user()):?><span><?=out(user()['name'])?></span> <button class="alt" onclick="logout()">Salir</button><?php else:?><button class="alt" onclick="show('login')">Ingresar</button><?php endif?></div></header><main>
<div class="tabs"><button class="active" onclick="tab('catalogo',this)">Tienda online</button><button onclick="tab('pos',this)">Punto de venta</button><?php if(user()):?><button onclick="tab('panel',this)">Panel</button><button onclick="tab('stock',this)">Stock</button><button onclick="tab('caja',this)">Caja y reportes</button><button onclick="tab('usuarios',this)">Usuarios</button><?php endif?></div>
<section id="catalogo" class="page active"><h2>Encontrá lo que necesitás</h2><p class="muted">Retirá tu pedido en el local. Podés confirmar acá o enviarlo por WhatsApp.</p><input id="search" oninput="filterProducts()" placeholder="Buscar por producto, categoría, código o variante"><div class="row" id="categories"><button class="alt" onclick="setCategory('',this)">Todo</button><?php foreach($categories as $c):?><button class="alt" onclick="setCategory(<?=json_encode($c)?>,this)"><?=out($c)?></button><?php endforeach?></div><div class="products" id="catalogProducts"><?php foreach($products as $p):?><article class="card product" data-search="<?=out(strtolower($p['name'].' '.$p['sku'].' '.$p['category'].' '.$p['variant']))?>"><span class="pill"><?=out($p['category'])?></span><h3><?=out($p['name'])?></h3><span class="muted"><?=out($p['sku'])?> <?=out($p['variant'])?></span><p class="price">$ <?=number_format($p['price'],0,',','.')?></p><p class="stock">Disponibles: <b><?=out($p['stock'])?></b></p><button onclick='add(<?=json_encode($p)?>)'>Agregar</button></article><?php endforeach?></div><div class="cart"><span id="cartText">Tu pedido está vacío</span><div class="row"><button class="alt" onclick="checkout('whatsapp')">Pedir por WhatsApp</button><button onclick="checkout('online')">Reservar para retirar</button></div></div></section>
<section id="pos" class="page"><h2>Punto de venta</h2><p class="muted">Escaneá el código o escribí el SKU. El lector funciona como teclado.</p><input id="barcode" onkeydown="if(event.key==='Enter')scan()" placeholder="Código de barras / SKU"><div class="products"><?php foreach($products as $p):?><article class="card product"><h3><?=out($p['name'])?></h3><span class="muted"><?=out($p['sku'])?></span><p class="price">$ <?=number_format($p['price'],0,',','.')?></p><p class="stock">Stock: <?=out($p['stock'])?></p><button onclick='add(<?=json_encode($p)?>)'>Sumar a venta</button></article><?php endforeach?></div><div class="cart"><span id="posCart">Sin productos</span><button onclick="checkout('pos')">Cobrar e imprimir</button></div></section>
<?php if(user()):?><section id="panel" class="page"><h2>Resumen de hoy</h2><div class="grid"><div class="card">Ventas hoy<div class="metric">$ <?=number_format($today,0,',','.')?></div></div><div class="card">Pedidos registrados<div class="metric"><?=$db->query('SELECT COUNT(*) FROM orders')->fetchColumn()?></div></div><div class="card">Productos activos<div class="metric"><?=count($products)?></div></div><div class="card">Alertas de stock<div class="metric"><?=count($low)?></div></div></div><h3>Últimos pedidos</h3><table><tr><th>#</th><th>Fecha</th><th>Canal</th><th>Cliente</th><th>Total</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=substr($o['created_at'],0,16)?></td><td><span class="pill"><?=out($o['channel'])?></span></td><td><?=out($o['customer'])?></td><td>$ <?=number_format($o['total'],0,',','.')?></td></tr><?php endforeach?></table></section>
<section id="stock" class="page"><div class="row"><h2>Inventario</h2><button onclick="show('product')">Nuevo producto</button></div><?php if($low):?><div class="notice"><b>Atención:</b> <?=count($low)?> producto(s) alcanzaron su stock mínimo.</div><?php endif?><table><tr><th>Producto</th><th>SKU</th><th>Disponible</th><th>Mínimo</th><th></th></tr><?php foreach($products as $p):?><tr><td><?=out($p['name'])?></td><td><?=out($p['sku'])?></td><td><?=$p['stock']?></td><td><?=$p['min_stock']?></td><td><button onclick="adjust(<?=$p['id']?>,'<?=out(addslashes($p['name']))?>')">Ajustar</button></td></tr><?php endforeach?></table></section>
<section id="caja" class="page"><h2>Caja y respaldos</h2><div class="grid"><div class="card"><b>Estado de caja</b><p class="metric"><?=$cash?'Abierta':'Cerrada'?></p><p class="muted"><?=$cash?'Apertura: $ '.number_format($cash['opening'],0,',','.'):''?></p><button onclick="cash()"><?=$cash?'Realizar cierre':'Abrir caja'?></button></div><div class="card"><b>Respaldo de información</b><p class="muted">Descargá una copia completa de pedidos, stock y caja.</p><button onclick="backup()">Descargar respaldo</button></div></div></section><?php endif?></main>
<section id="usuarios" class="page"><div class="row"><h2>Usuarios</h2><?php if(user()['role']==='admin'):?><button onclick="show('user')">Nuevo usuario</button><?php endif?></div><table><tr><th>Nombre</th><th>Email</th><th>Rol</th></tr><?php foreach($users as $u):?><tr><td><?=out($u['name'])?></td><td><?=out($u['email'])?></td><td><span class="pill"><?=out($u['role'])?></span></td></tr><?php endforeach?></table></section><?php endif?></main>
<div id="modal" class="modal"><div class="dialog" id="dialog"></div></div><script>
let cart=[],selectedCategory='';const productData=<?=json_encode($products)?>;function tab(id,b){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');b.classList.add('active')}function setCategory(c,b){selectedCategory=c;filterProducts();document.querySelectorAll('#categories button').forEach(x=>x.style.outline='');b.style.outline='2px solid var(--blue)'}function filterProducts(){let q=(search.value||'').toLowerCase();document.querySelectorAll('#catalogProducts .product').forEach(x=>x.style.display=(x.dataset.search.includes(q)&&(!selectedCategory||x.dataset.search.includes(selectedCategory.toLowerCase())))?'':'none')}function scan(){let p=productData.find(x=>x.sku.toLowerCase()===barcode.value.trim().toLowerCase());if(!p)return alert('No encontramos ese código');add(p);barcode.value='';barcode.focus()}function show(type){let d=document.getElementById('dialog');let forms={login:`<h2>Ingresar</h2><input id="email" placeholder="Email" value="admin@local"><input id="pass" type="password" placeholder="Contraseña" value="admin123"><button onclick="login()">Ingresar</button>`,product:`<h2>Nuevo producto</h2><input id="name" placeholder="Nombre"><input id="sku" placeholder="SKU"><input id="category" placeholder="Categoría"><input id="variant" placeholder="Variante (color, talle)"><input id="price" type="number" placeholder="Precio"><input id="stock" type="number" placeholder="Stock inicial"><input id="min" type="number" placeholder="Stock mínimo" value="3"><button onclick="newProduct()">Guardar</button>`,user:`<h2>Nuevo usuario</h2><input id="uname" placeholder="Nombre"><input id="uemail" placeholder="Email"><input id="upass" type="password" placeholder="Contraseña"><select id="urole"><option value="vendedor">Vendedor</option><option value="admin">Administración</option></select><button onclick="newUser()">Guardar</button>`};d.innerHTML=forms[type];document.getElementById('modal').classList.add('show')}function close(){modal.classList.remove('show')}modal.onclick=e=>{if(e.target===modal)close()};async function api(x){let r=await fetch('',{method:'POST',body:JSON.stringify(x)}),j=await r.json();if(j.error){alert(j.error);throw 0}return j}function login(){api({action:'login',email:email.value,password:pass.value}).then(()=>location.reload())}function logout(){api({action:'logout'}).then(()=>location.reload())}function add(p){let x=cart.find(i=>i.id==p.id);if(x){if(x.qty<p.stock)x.qty++}else cart.push({...p,qty:1});renderCart()}function renderCart(){let n=cart.reduce((s,x)=>s+x.qty,0),t=cart.reduce((s,x)=>s+x.qty*x.price,0),s=n?`${n} producto(s) · $ ${t.toLocaleString('es-AR')}`:'Sin productos';cartText.textContent=n?`Tu pedido: ${s}`:'Tu pedido está vacío';posCart.textContent=s}function receipt(id,customer,payment,total){let lines=cart.map(x=>`<tr><td>${x.name}</td><td>${x.qty}</td><td>$ ${(x.qty*x.price).toLocaleString('es-AR')}</td></tr>`).join('');let w=open('','_blank');w.document.write(`<main style="font:14px sans-serif;max-width:320px"><h2>VendeSimple</h2><p>Comprobante interno #${id}<br>${new Date().toLocaleString()}<br>Cliente: ${customer}</p><table>${lines}</table><h3>Total: $ ${total.toLocaleString('es-AR')}</h3><p>Pago: ${payment}</p><p>Retiro en local · Gracias</p></main>`);w.print()}function checkout(channel){if(!cart.length)return alert('Agregá al menos un producto');let customer=prompt(channel==='online'||channel==='whatsapp'?'Tu nombre:':'Cliente (opcional):','Consumidor final');if(customer===null)return;let payment=channel==='pos'?prompt('Medio de pago:','Efectivo'):'pendiente';api({action:'order',channel,customer,payment,items:cart.map(x=>({id:x.id,qty:x.qty}))}).then(x=>{if(channel==='whatsapp'){let m=`Hola, quiero retirar el pedido #${x.order}. Total $ ${x.total.toLocaleString('es-AR')}.`;open('https://wa.me/?text='+encodeURIComponent(m),'_blank')}if(channel==='pos')receipt(x.order,customer,payment,x.total);else alert(`Pedido #${x.order} reservado por 2 horas para retirar en el local`);location.reload()})}function adjust(id,name){let q=prompt(`Ajuste para ${name}. Usá negativo para restar:`,`0`);if(q===null)return;let reason=prompt('Motivo:','Ajuste de inventario');api({action:'stock',product_id:id,qty:q,reason}).then(()=>location.reload())}function newProduct(){api({action:'product',name:name.value,sku:sku.value,category:category.value,variant:variant.value,price:price.value,stock:stock.value,min_stock:min.value}).then(()=>location.reload())}function newUser(){api({action:'user',name:uname.value,email:uemail.value,password:upass.value,role:urole.value}).then(()=>location.reload())}function cash(){let amount=prompt('Importe de '+<?=json_encode($cash?'cierre':'apertura')?>+':','0');if(amount!==null)api({action:'cash',amount}).then(()=>location.reload())}async function backup(){let r=await fetch('',{method:'POST',body:JSON.stringify({action:'backup'})});let a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download='pedidos-pos-respaldo.sqlite';a.click();URL.revokeObjectURL(a.href)}
function checkout(channel){if(!cart.length)return alert('Agregá al menos un producto');let customer=prompt(channel==='pos'?'Cliente (opcional):':'Tu nombre:','Consumidor final');if(customer===null)return;let payment=channel==='pos'?prompt('Medio de pago:','Efectivo'):'transferencia';api({action:'order',channel,customer,payment,items:cart.map(x=>({id:x.id,qty:x.qty}))}).then(x=>{if(channel==='pos'){receipt(x.order,customer,payment,x.total);location.reload();return}let d=document.getElementById('dialog');d.innerHTML=`<h2>Pedido #${x.order} reservado</h2><p>Total exacto: <b>$ ${x.total.toLocaleString('es-AR')}</b></p><p>Transferí a <b>${x.bank.bank_holder}</b><br>Alias: <b>${x.bank.bank_alias}</b><br>CBU: <b>${x.bank.bank_cbu}</b></p><p class="muted">Reservado hasta ${x.deadline}. Tu pago será verificado manualmente.</p><input id="proof" type="file" accept="image/jpeg,image/png,application/pdf"><button onclick="sendProof(${x.order},'${x.token}')">Subir comprobante</button><button class="alt" onclick="window.open('https://wa.me/?text='+encodeURIComponent('Hola, informé la transferencia del pedido #${x.order}'),'_blank')">Avisar por WhatsApp</button>`;modal.classList.add('show')})}async function sendProof(order,token){let file=proof.files[0];if(!file)return alert('Elegí un comprobante');let f=new FormData();f.append('action','upload_proof');f.append('order_id',order);f.append('token',token);f.append('proof',file);let r=await fetch('',{method:'POST',body:f}),j=await r.json();if(j.error)return alert(j.error);alert('Comprobante recibido. El pago quedó pendiente de verificación.');location.reload()}
</script></body></html>
